public static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }
    if (!ignoreCase) {
        return str.endsWith(suffix);
    } else {
        int len = suffix.length();
        return str.length() >= len && str.substring(str.length() - len).equalsIgnoreCase(suffix);
    }
}

public static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.equalsIgnoreCase(suffix) || str.endsWith(suffix.toLowerCase());
    } else {
        return str.endsWith(suffix) || str.endsWith(suffix.toUpperCase());
    }
}

